def augment_systematic_notes(notes,table,cite):
 by={n['slug']:n for n in notes};out={}
 for slug,heading,sources,ps in supplement_records():
  n=by[slug];assert 'id="systematic-supplement"' not in n['body']
  body='<section id="systematic-supplement"><h2>'+heading+'</h2>'+''.join('<p>'+p+'</p>' for p in ps)+'<p class="research-small">'+''.join(cite(k,'原論文・確認範囲') for k in sources)+'</p></section>'
  n['body']+=body;n['updated']='2026-11-14';n['sources']=list(dict.fromkeys(n['sources']+sources));out[slug]=heading
 return out
